export function makeLegacyRawPack(): Record<string, unknown> {
  const ex = (kind: string, extra: Record<string, unknown>) => ({
    id: `lg-ex-${kind}`,
    conceptId: "c-basic",
    prompt: `${kind} prompt ___`,
    explanation: `${kind} explanation.`,
    vocabulary: ["w-caffe"],
    reviewOf: [],
    answers: kind === "order" ? ["Un caffè per favore"] : ["Un caffè"],
    allowTypo: false,
    errors: [],
    kind,
    ...extra,
  });
  return {
    schemaVersion: 1,
    id: "lg-legacy",
    version: "1.0.0",
    language: "it",
    title: "Legacy",
    sourceLanguage: "en",
    description: "Synthetic v1 pack for adapter tests.",
    attribution: "Fixture.",
    units: [{ id: "u-basic", title: "Base", objective: "Basics." }],
    concepts: [
      {
        id: "c-basic",
        title: "Caffè",
        explanation: "Coffee basics.",
        examples: [{ target: "caffè", meaning: "coffee" }],
        commonError: "None.",
      },
    ],
    vocabulary: [
      { id: "w-caffe", word: "caffè", meaning: "coffee", partOfSpeech: "noun", gender: "masculine", example: "un caffè" },
      { id: "w-grazie", word: "grazie", meaning: "thank you", partOfSpeech: "interjection", example: "grazie" },
    ],
    media: [
      {
        id: "aud-basic",
        url: "/audio/it/basic.mp3",
        sha256: "c3".repeat(32),
        transcript: "Un caffè.",
        attribution: "Fixture.",
      },
    ],
    lessons: [
      {
        id: "lg-lesson",
        unitId: "u-basic",
        title: "Lezione",
        objective: "Learn.",
        cefr: "A1",
        prerequisites: [],
        conceptIds: ["c-basic"],
        vocabulary: ["w-caffe", "w-grazie"],
        explanation: "Coffee words.",
        examples: [
          { target: "un caffè", meaning: "a coffee" },
          { target: "grazie", meaning: "thank you" },
        ],
        exercises: [
          ex("choice", {
            id: "lg-ex-meet",
            mode: "recognition",
            prompt: "Meet caffè: which means coffee?",
            options: ["caffè", "tè"],
            answers: ["caffè"],
            vocabulary: [],
          }),
          ex("translate", { mode: "production" }),
          ex("order", {
            mode: "production",
            tokens: ["Un", "caffè", "per", "favore"],
          }),
          ex("dictation", { mode: "listening", audioId: "aud-basic" }),
        ],
        optionalExerciseIds: [],
      },
    ],
    dialogues: [],
  };
}
